import React, { useState, useEffect } from 'react';
import { db } from '../data/db';
import { useLiveQuery } from "dexie-react-hooks";

export const FormularioPreventa = () => {
  const [formData, setFormData] = useState({ cliente: '', producto: '', cantidad: 1 });
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [sincronizando, setSincronizando] = useState(false);
  const [pedidosEnServidor, setPedidosEnServidor] = useState([]);

  const pedidosLocales = useLiveQuery(() => db.pedidos.toArray());

  // Función para traer datos del servidor central
  const consultarServidorCentral = async () => {
    try {
      // Si estamos en la lap usamos localhost, si no, la IP
      const url = window.location.hostname === 'localhost' 
        ? 'http://localhost:3001/api/pedidos' 
        : 'http://192.168.1.221:3001/api/pedidos';

      const res = await fetch(url);
      if (res.ok) {
        const data = await res.json();
        setPedidosEnServidor(data);
      }
    } catch (e) {
      console.log("Conectando al servidor central...");
    }
  };

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    
    // Consultar pedidos nuevos cada 3 segundos
    const intervalo = setInterval(consultarServidorCentral, 3000);
    
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
      clearInterval(intervalo);
    };
  }, []);

  const guardarLocalmente = async (e) => {
    e.preventDefault();
    await db.pedidos.add({ ...formData, fecha: new Date().toISOString(), sincronizado: 0 });
    setFormData({ cliente: '', producto: '', cantidad: 1 });
    alert("✔ Guardado en memoria local");
  };

  const enviarALaLaptop = async () => {
    if (!isOnline) return alert("Sin conexión");
    setSincronizando(true);
    const pendientes = await db.pedidos.where('sincronizado').equals(0).toArray();

    for (const p of pendientes) {
      try {
        const res = await fetch('http://192.168.1.221:3001/api/pedidos', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(p)
        });
        if (res.ok) await db.pedidos.update(p.id, { sincronizado: 1 });
      } catch (e) { break; }
    }
    setSincronizando(false);
    consultarServidorCentral();
  };

  return (
    <div style={{ padding: '20px', maxWidth: '500px', margin: 'auto', fontFamily: 'Arial' }}>
      <div style={{ background: isOnline ? '#d4edda' : '#f8d7da', padding: '10px', textAlign: 'center', borderRadius: '8px' }}>
        <strong>{isOnline ? '🟢 MODO ONLINE' : '🔴 MODO OFFLINE'}</strong>
      </div>
      
      <form onSubmit={guardarLocalmente} style={{ display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '20px' }}>
        <h2 style={{ textAlign: 'center' }}>Preventa MakingPIT</h2>
        <input style={{ padding: '12px' }} type="text" placeholder="Cliente" value={formData.cliente} onChange={e => setFormData({...formData, cliente: e.target.value})} required />
        <input style={{ padding: '12px' }} type="text" placeholder="Producto" value={formData.producto} onChange={e => setFormData({...formData, producto: e.target.value})} required />
        <button type="submit" style={{ padding: '15px', background: '#28a745', color: 'white', fontWeight: 'bold', border: 'none', borderRadius: '5px' }}>
          GUARDAR PEDIDO
        </button>
      </form>

      <button onClick={enviarALaLaptop} style={{ marginTop: '10px', width: '100%', padding: '15px', background: '#007bff', color: 'white', border: 'none', borderRadius: '5px' }}>
        {sincronizando ? 'SINCRONIZANDO...' : 'SINCRONIZAR CON SERVIDOR'}
      </button>

      {/* Historial Local del Dispositivo */}
      <div style={{ marginTop: '25px' }}>
        <h4 style={{ borderBottom: '1px solid #ddd' }}>📦 Registros de este equipo:</h4>
        {pedidosLocales?.map(p => (
          <div key={p.id} style={{ fontSize: '14px', padding: '5px 0', borderBottom: '1px solid #eee' }}>
            {p.cliente} - {p.producto} {p.sincronizado ? '✅' : '⏳'}
          </div>
        ))}
      </div>

      {/* PANEL CENTRAL: Aquí aparecerá lo que envíe el celular */}
      <div style={{ marginTop: '25px', background: '#343a40', color: 'white', padding: '15px', borderRadius: '10px' }}>
        <h4 style={{ margin: '0 0 10px 0', color: '#ffc107' }}>🖥️ Servidor Central (Laptop)</h4>
        {pedidosEnServidor.length === 0 ? 
          <p style={{ fontSize: '12px', color: '#adb5bd' }}>Esperando sincronización de dispositivos...</p> : 
          pedidosEnServidor.map((p, i) => (
            <div key={i} style={{ background: '#495057', margin: '5px 0', padding: '10px', borderRadius: '5px', borderLeft: '4px solid #ffc107' }}>
              <strong>{p.cliente}</strong> - {p.producto}
            </div>
          ))
        }
      </div>
    </div>
  );
};
